            , QTY311,QTY312,QTY313,QTY314,QTY315,QTY316,QTY317,QTY318,QTY319,QTY320
            , QTY321,QTY322,QTY323,QTY324,QTY325,QTY326,QTY327,QTY328,QTY329,QTY330
            , QTY331,QTY332,QTY333,QTY334,QTY335,QTY336,QTY337,QTY338,QTY339,QTY340
            , QTY341,QTY342,QTY343,QTY344,QTY345,QTY346,QTY347,QTY348,QTY349,QTY350
            , QTY351,QTY352,QTY353,QTY354,QTY355,QTY356,QTY357,QTY358,QTY359,QTY360
            , QTY361,QTY362,QTY363,QTY364
            , WQTY01,WQTY02,WQTY03,WQTY04,WQTY05,WQTY06,WQTY07,WQTY08,WQTY09,WQTY10
            , WQTY11,WQTY12,WQTY13,WQTY14,WQTY15,WQTY16,WQTY17,WQTY18,WQTY19,WQTY20
            , WQTY21,WQTY22,WQTY23,WQTY24,WQTY25,WQTY26,WQTY27,WQTY28,WQTY29,WQTY30
            , WQTY31,WQTY32,WQTY33,WQTY34,WQTY35,WQTY36,WQTY37,WQTY38,WQTY39,WQTY40
            , WQTY41,WQTY42,WQTY43,WQTY44,WQTY45,WQTY46,WQTY47,WQTY48,WQTY49,WQTY50
            , WQTY51,WQTY52
         FROM SCP_XLS_PSI_GLOBAL_ESS A
              /* ★LEFT OUTER JOIN 유지(변환표준 H-3) : 아래 ON절의 A.CREATE_FROM_YYYYMMDD = (서브쿼리)는 */
              /*   보존측(A) 단독 조건이라, (+)로 바꾸면 짝 없는 A행까지 걸러내는 WHERE 필터가 되어 결과 행수가 달라짐. */
              /*   (+)로 의미 표현 불가 → ANSI JOIN 그대로 유지. */
              LEFT OUTER JOIN SCP_MST_OUTSOURCING_CAPA B
                ON A.DIVISION_ID = B.DIVISION_ID
               AND A.CREATE_FROM_YYYYMMDD = (SELECT DISTINCT PLAN_START_YYYYMMDD FROM SCP_XLS_PSI_GLOBAL_ESS)   /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선' - 중장기 대응 */
               AND A.ITEM_ID   = B.ITEM_ID
               AND A.FROM_SITE = B.PLANT_SITE_ID
               /* AND X.PROD_LINE = Y.LINE_ID */
              INNER JOIN SCM_MST_SITE C   /* ESS 외주 Line별 생산 Target 관련 OSP_YN로직 수정 */
                ON C.DIVISION_ID = A.DIVISION_ID
               AND C.SCM_SITE_ID = A.FROM_SITE
               AND (C.OSP_YN = 'N'
                 OR (C.OSP_YN = 'Y' AND NVL(C.ATTRIBUTE1, 'N') IN ('N','')))
        WHERE 0 = 0
          AND A.MEASURE IN ('PACK_PROD','CELL_PROD')
       /* ESS 외주 Line별 생산 Target 관련 OSP_YN로직 수정 : OSP 이면서 Line Capa 대상 */
       UNION
       SELECT A.DIVISION_ID
            , A.PLAN_START_YYYYMMDD
            , A.PLAN_TYPE
            , A.SEQ
            , A.OPERATION_GROUP
            , A.OPERATION_GROUP_NAME
            , A.FROM_SITE
            , NVL((SELECT SA.SITE_DESCRIPTION
                            FROM SCM_MST_SITE SA
                           WHERE SA.SCM_SITE_ID = A.FROM_SITE
                             AND ROWNUM = 1), '/')   AS FROM_SITE_DESCRIPTION
            , A.ATTRIBUTE9   AS OPERATION_ID
            , A.ITEM_ID
            , A.NICK_NAME
            , A.PROD_LINE
            , (CASE WHEN A.OPERATION_GROUP = 'A' THEN 0 ELSE B.DAILY_CAPACITY END)   AS DAILY_CAPA_QTY
            , (CASE WHEN A.OPERATION_GROUP = 'P' THEN B.TACT_TIME
                    WHEN A.OPERATION_GROUP = 'A' THEN B.TACT_TIME
                    ELSE B.DAILY_CAPACITY END)   AS TACT_TIME
            , A.MEASURE
            , A.MEASURE_LABEL
            , A.SORT_ORDER_NO
            , A.XLS_KEY1
            , QTY001,QTY002,QTY003,QTY004,QTY005,QTY006,QTY007,QTY008,QTY009,QTY010
