            , WQTY01,WQTY02,WQTY03,WQTY04,WQTY05,WQTY06,WQTY07,WQTY08,WQTY09,WQTY10
            , WQTY11,WQTY12,WQTY13,WQTY14,WQTY15,WQTY16,WQTY17,WQTY18,WQTY19,WQTY20
            , WQTY21,WQTY22,WQTY23,WQTY24,WQTY25,WQTY26,WQTY27,WQTY28,WQTY29,WQTY30
            , WQTY31,WQTY32,WQTY33,WQTY34,WQTY35,WQTY36,WQTY37,WQTY38,WQTY39,WQTY40
            , WQTY41,WQTY42,WQTY43,WQTY44,WQTY45,WQTY46,WQTY47,WQTY48,WQTY49,WQTY50
            , WQTY51,WQTY52
         FROM SCP_XLS_PSI_GLOBAL_ESS A
            , SCP_MST_TACT_TIME_OSP  B   /* ESS 외주 Line별 생산 Target 관련 OSP_YN로직 수정 */
            , SCM_MST_SITE           C
        WHERE A.DIVISION_ID = B.DIVISION_ID
          AND A.CREATE_FROM_YYYYMMDD = (SELECT DISTINCT PLAN_START_YYYYMMDD FROM SCP_XLS_PSI_GLOBAL_ESS)   /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선' - 중장기 대응 */
          AND A.ITEM_ID   = B.ITEM_ID
          AND A.FROM_SITE = B.PLANT_SITE_ID
          AND A.PROD_LINE = B.LINE_ID
          AND C.DIVISION_ID = A.DIVISION_ID
          AND C.SCM_SITE_ID = A.FROM_SITE
          AND C.OSP_YN = 'Y'
          AND NVL(C.ATTRIBUTE1, 'N') = 'Y'
          AND A.MEASURE IN ('PACK_PROD','CELL_PROD')
       UNION
       SELECT DISTINCT
              A.DIVISION_ID
            , A.PLAN_START_YYYYMMDD
            , A.PLAN_TYPE
            , A.SEQ
            , A.OPERATION_GROUP
            , A.OPERATION_GROUP_NAME
            , A.FROM_SITE
            , NVL((SELECT SA.SITE_DESCRIPTION
                            FROM SCM_MST_SITE SA
                           WHERE SA.SCM_SITE_ID = A.FROM_SITE
                             AND ROWNUM = 1), '/')   AS FROM_SITE_DESCRIPTION
            , A.ATTRIBUTE9   AS OPERATION_ID
            , '-'   AS ITEM_ID
            , '-'   AS NICK_NAME
            , A.PROD_LINE
            , 0   AS DAILY_CAPA_QTY
            , 0   AS TACT_TIME
            , B.MEASURE
            , B.MEASURE_LABEL
            , TO_NUMBER(B.SORT_ORDER_NO)   AS SORT_ORDER_NO
            , 99999   AS XLS_KEY1
