         FROM SCP_XLS_PSI_GLOBAL_ESS A
            , SUB                    B
        /* --LEFT OUTER  JOIN SCP_MST_OUTSOURCING_CAPA Y WITH (NOLOCK) */
        /* --  ON X.DIVISION_ID  = Y.DIVISION_ID */
        /* -- AND X.ITEM_ID      = Y.ITEM_ID */
        /* -- AND X.FROM_SITE    = Y.PLANT_SITE_ID */
        WHERE A.OPERATION_GROUP = B.OPERATION_GROUP
          AND A.CREATE_FROM_YYYYMMDD = (SELECT DISTINCT PLAN_START_YYYYMMDD FROM SCP_XLS_PSI_GLOBAL_ESS)   /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선' - 중장기 대응 */
